import {AWAKENER_SKILLS,heroLoadout,heroScale,heroRadius} from './awakener-skills.js?v=1.7.40';
export function awakenerDetails(character){const kit=AWAKENER_SKILLS[character.sprite];return kit?`<div class="awakener-details">${['e','q'].map(key=>{const s=kit[key];return `<p><b>${key.toUpperCase()} · ${s.name}</b><br>${s.description}<br><small>기본 반경 ${Math.round(s.radius*1.25)} · 광역 감응 연구 적용 · 고유 쿨타임 ${s.cd}초 · 기본 계수 ${s.coefficient} × ${s.hits}회 × 마력 × 초능력 배율 · 재사용시간 감소 미적용</small></p>`;}).join('')}</div>`:'';}
export function heroButtons(game){const kit=heroLoadout(game),state=game.heroState,now=game.elapsed;return ['e','q'].map(key=>{const s=kit[key],remaining=game.heroCooldowns[key];const recast=key==='q'&&((game.character.sprite==='akane'&&state.soloUntil>now&&now>=state.soloStart+4)||(game.character.sprite==='raven'&&state.witchUntil>now)||(game.character.sprite==='zanhong'&&state.zanhongRecastUntil>now));return `<button class="hero-skill-button" data-action="hero-cast" data-id="${key}" ${game.state!=='playing'||(!recast&&remaining>0)?'disabled':''} title="${s.description} 기본 피해 ${Math.round(s.coefficient*heroScale(game))} × ${s.hits}회. 범위 반경 ${Math.round(heroRadius(game,s.radius))}. 고유 쿨타임 ${s.cd}초"><kbd>${key.toUpperCase()}</kbd><span>${s.name}</span><b>${recast?(game.character.sprite==='zanhong'?'2차 시전':'종결'):remaining>0?remaining.toFixed(1)+'s':'준비'}</b></button>`;}).join('');}
